// Backing Vocal Tucker: Suno Studio audio effect for the BACKING VOCALS stem (applied to rendered audio, not a lyric tag).
// TUCK NOTE: the 'tuck' stage is a STATIC gain reduction (a fixed g.dbToLin scale), NOT a lead-driven sidechain
// duck. No sidechain / lead input is available to these effects, so the tuck simply lowers the backing vocals by
// a fixed dB amount so they sit behind the lead; it does not respond dynamically to the lead's level.
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Band-limit: g.biquad highpass at 'hp' then g.biquad lowpass at 'lp' to pull the backing vocals out of
//      the lead's core band.
//   3. Presence cut: g.biquad peaking near 3kHz driven by 'presence cut' (negative gainDb) to reduce competition.
//   4. Tilt EQ: lowshelf +tilt near 250Hz and highshelf -tilt near 5kHz (opposite via g.mul by -1), one 'tilt' param.
//   5. Tuck: static attenuation. tuckLin = g.dbToLin(-tuck) so a positive 'tuck' dB lowers level; g.mul the signal.
//   6. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   7. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the shelf/peaking g.biquad stages pass a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var tuckDb = g.input('tuck');
  var hp = g.input('hp');
  var lp = g.input('lp');
  var presCutDb = g.input('presence cut');
  var tiltDb = g.input('tilt');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var tuckLin = g.dbToLin(g.mul(tuckDb, g.constant(-1)));
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var negTilt = g.mul(tiltDb, g.constant(-1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var hpf = g.biquad({ input: trimmed, cutoff: hp, resonance: g.constant(0.707), mode: 'highpass' });
    var lpf = g.biquad({ input: hpf, cutoff: lp, resonance: g.constant(0.707), mode: 'lowpass' });
    var presCut = g.biquad({ input: lpf, cutoff: g.constant(3000), resonance: g.constant(0.9), mode: 'peaking', gainDb: presCutDb });
    var low = g.biquad({ input: presCut, cutoff: g.constant(250), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: tiltDb });
    var tilted = g.biquad({ input: low, cutoff: g.constant(5000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: negTilt });
    var tucked = g.mul(tilted, tuckLin);
    var wet = g.lerp(mix, trimmed, tucked);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
